// ─────────────────────────────────────────────────────────────
// Sound effects via audioplayers. WAV assets live in
// assets/sounds and are generated by tool/generate_sounds.py.
// Singleton so the mute choice on the Home screen reaches the game.
// ─────────────────────────────────────────────────────────────

import 'package:audioplayers/audioplayers.dart';
import 'package:shared_preferences/shared_preferences.dart';

class SoundService {
  SoundService._();

  static final SoundService instance = SoundService._();

  static const String _muteKey = 'rope-untangle-muted';

  final List<AudioPlayer> _pool = <AudioPlayer>[];
  int _cursor = 0;
  bool _initialized = false;
  bool muted = false;

  void _ensurePool() {
    if (_initialized) return;
    _initialized = true;
    for (int i = 0; i < 5; i++) {
      _pool.add(AudioPlayer());
    }
  }

  Future<void> loadMuted() async {
    final SharedPreferences prefs = await SharedPreferences.getInstance();
    muted = prefs.getBool(_muteKey) ?? false;
  }

  Future<bool> toggleMuted() async {
    muted = !muted;
    final SharedPreferences prefs = await SharedPreferences.getInstance();
    await prefs.setBool(_muteKey, muted);
    return muted;
  }

  Future<void> _play(String file) async {
    if (muted) return;
    _ensurePool();
    final AudioPlayer player = _pool[_cursor];
    _cursor = (_cursor + 1) % _pool.length;
    await player.stop();
    await player.play(AssetSource('sounds/$file'));
  }

  void select() => _play('select.wav');
  void move() => _play('move.wav');
  void error() => _play('error.wav');
  void hint() => _play('hint.wav');
  void win() => _play('win.wav');

  Future<void> dispose() async {
    for (final AudioPlayer p in _pool) {
      await p.dispose();
    }
    _pool.clear();
    _initialized = false;
  }
}
